package co.unicauca.taller08;
import co.unicauca.taller08.adapter.ExternalQuestionDTO; import co.unicauca.taller08.builder.MultipleChoiceQuestionBuilder; import co.unicauca.taller08.domain.*; import co.unicauca.taller08.facade.QuestionBankFacade;
import org.junit.jupiter.api.Test; import java.util.Arrays; import static org.junit.jupiter.api.Assertions.*;
class Taller08IntegrationTest {
 private Question question(QuestionBankFacade f){return f.createQuestion(new MultipleChoiceQuestionBuilder(),"¿Patrón?","Contexto",DifficultyLevel.FACIL,"Software","Diseño","Diseño","Autor","Justificación","Fuente",Arrays.asList(new Option("A","Builder"),new Option("B","Adapter")),"A");}
 @Test void stateTransitionsAndIllegalTransition(){QuestionBankFacade f=new QuestionBankFacade();Question q=question(f);assertThrows(IllegalStateException.class,q::publish);f.submitForReview(q);f.assignReviewer(q);f.approve(q);f.publish(q);assertEquals("PUBLICADA",q.getStatus());}
 @Test void facadeTemplateDecoratorAndAdapter(){QuestionBankFacade f=new QuestionBankFacade();Question q=question(f);f.submitForReview(q);f.assignReviewer(q);f.approve(q);f.publish(q);assertTrue(f.evaluate(q,"A").isCorrect());assertTrue(f.decorate(q,"dificultad").describe().contains("Dificultad alta"));Question imported=f.importQuestion(new ExternalQuestionDTO("verdadero_falso","El cielo es azul.","Verdadero"));assertEquals(QuestionType.TRUE_FALSE,imported.getType());Question external=f.importExternalQuestion();assertEquals(QuestionType.OPEN,external.getType());assertEquals("Bogotá",external.getCorrectAnswer());}
 @Test void publishQuestionValidatesApprovesAndPublishes(){QuestionBankFacade f=new QuestionBankFacade();Question q=question(f);f.submitForReview(q);f.assignReviewer(q);f.publishQuestion(q);assertEquals("PUBLICADA",q.getStatus());}
 @Test void stackedDecoratorsAccumulateFeatures(){QuestionBankFacade f=new QuestionBankFacade();Question q=question(f);co.unicauca.taller08.decorator.QuestionFeature d=f.decorate(f.decorate(q,"dificultad"),"revision");assertTrue(d.describe().contains("Dificultad alta"));assertTrue(d.describe().contains("MARCADA PARA REVISIÓN"));assertEquals(1.0,d.getScore());}
}
